(function(){
  // The checkerboard is BUILT here rather than shipped as an image, so the
  // measurement is of the reader's own browser and cannot be a picture of
  // someone else's result.
  var el = document.getElementById("hl-demo");
  if (el) {
    var N = 256, F = 16, S = N / F;
    var lin = function(c){ var s = c / 255; return s <= 0.04044993 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4); };
    var enc = function(l){ var s = l <= 0.0031308 ? l * 12.92 : 1.055 * Math.pow(l, 1 / 2.4) - 0.055; return Math.round(s * 255); };
    var a = document.createElement("canvas"); a.width = a.height = N;
    var ax = a.getContext("2d", { willReadFrequently: true });
    var im = ax.createImageData(N, N);
    for (var y = 0; y < N; y++) for (var x = 0; x < N; x++) {
      var v = ((x + y) & 1) ? 255 : 0, i = (y * N + x) * 4;
      im.data[i] = im.data[i + 1] = im.data[i + 2] = v; im.data[i + 3] = 255;
    }
    ax.putImageData(im, 0, 0);
    var b = document.createElement("canvas"); b.width = b.height = S;
    var bx = b.getContext("2d", { willReadFrequently: true });
    bx.imageSmoothingEnabled = true; bx.imageSmoothingQuality = "high";
    bx.drawImage(a, 0, 0, S, S);
    var bd = bx.getImageData(0, 0, S, S).data, cs = 0, cn = 0;
    for (var p = 0; p < bd.length; p += 4) { cs += bd[p]; cn++; }
    var canvasMean = cs / cn;
    var ls = 0;
    for (var oy = 0; oy < S; oy++) for (var ox = 0; ox < S; ox++) {
      var sum = 0;
      for (var dy = 0; dy < F; dy++) for (var dx = 0; dx < F; dx++)
        sum += lin(im.data[(((oy * F + dy) * N) + (ox * F + dx)) * 4]);
      ls += enc(sum / (F * F));
    }
    var linMean = ls / (S * S);
    var cell = function(v, label) {
      var g = Math.round(v);
      return '<div class="cell"><span class="sw" style="background:rgb(' + g + ',' + g + ',' + g + ')"></span>' +
             '<span class="n">' + v.toFixed(2) + '</span><br><span class="lbl">' + label + '</span></div>';
    };
    el.innerHTML = cell(canvasMean, "canvas drawImage") + cell(linMean, "averaged over light") +
      '<div class="cell" style="text-align:left;max-width:16em"><span class="lbl">The correct answer is 187.5. ' +
      'Your browser reports ' + canvasMean.toFixed(2) + ', which is the average of the codes rather than of the light.</span></div>';
  }

  // The six rows are the page's argument, so they live in one place and render
  // rather than being restated in prose where the copies could drift.
  var t = document.getElementById("hl-table");
  if (!t) return;
  var rows = [
    ["the shipped resize", "score against its own reference", "a defective reference scores itself perfectly"],
    ["the quality target", "the same ssimulacra2 number", "a clean reference is easier to match, so 70 bought a worse file"],
    ["dropping a resize step", "mean linear luminance", "insensitive here; ssimulacra2 against ground truth said +27.5"],
    ["jpegtran rotation", "the exit code", "off the block grid it degrades and still exits 0"],
    ["a claim about image-rs", "resize to the current size", "both entry points short circuit, so the kernel never ran"],
    ["a container contract test", "the first 12 files on disk", "readdir order differs by filesystem, so CI and the laptop sampled different files"]
  ];
  var html = '<div class="row head"><span>what looked fine</span><span>the instrument</span><span>what it could not see</span></div>';
  for (var i = 0; i < rows.length; i++)
    html += '<div class="row"><span>' + rows[i][0] + '</span><span>' + rows[i][1] + '</span><span>' + rows[i][2] + '</span></div>';
  t.innerHTML = html;
})();
